import { MONSTER_DATA, MONSTER_ZONES } from "@hunt/hunt-data/monarch";
import {
  CapstoneInfoBox,
  FlavorText,
  getLocalSolvedPuzzleMap,
  ShowAllPuzzmonInfoBox,
} from "@hunt/puzzle-components";
import React, { useState } from "react";

const bubbleCovePuzzmon = MONSTER_DATA[MONSTER_ZONES.BUBBLE_COVE];
const CLUES: [string, number][] = [
  ["grrrrrrravalax", 3],
  ["healibut", 4],
  ["splorkdine", 2],
  ["barelythereacuda", 3],
  ["steve", 1],
  ["troutorque", 6],
  ["splorkdine", 1],
  ["grrrrrrravalax", 4],
  ["barelythereacuda", 1],
  ["troutorque", 2],
  ["el_tuna_diablo", 7],
  ["healibut", 1],
  ["el_tuna_diablo", 3],
  ["steve", 4],
];
const BUBBLE_COVE_PUZZMON_SLUGS = new Set(
  CLUES.map(([puzzmonSlug]) => puzzmonSlug),
);

const getClues = (showAllPuzzmon: boolean): string[] => {
  const localSolvedPuzzleMap = getLocalSolvedPuzzleMap();
  const solvedPuzzmonSlugs = Object.values(localSolvedPuzzleMap)
    .filter((entry): entry is { puzzmonSlug: string } =>
      Boolean(
        entry.puzzmonSlug && BUBBLE_COVE_PUZZMON_SLUGS.has(entry.puzzmonSlug),
      ),
    )
    .map(({ puzzmonSlug }) => puzzmonSlug);

  return CLUES.map(([puzzmonSlug, count]) => {
    if (showAllPuzzmon || solvedPuzzmonSlugs.includes(puzzmonSlug)) {
      const puzzmonName = bubbleCovePuzzmon[puzzmonSlug].name;
      return `${puzzmonName} ${count}`;
    }
    return `??? ${count}`;
  });
};

const PuzzleComponent = () => {
  const [showAllPuzzmon, setShowAllPuzzmon] = useState(false);
  const clues = getClues(showAllPuzzmon);

  return (
    <div className="flex flex-col gap-4">
      <CapstoneInfoBox />
      {(showAllPuzzmon || clues.some((clue) => clue.includes("???"))) && (
        <ShowAllPuzzmonInfoBox
          showAllPuzzmon={showAllPuzzmon}
          onToggle={() => {
            setShowAllPuzzmon(!showAllPuzzmon);
          }}
        />
      )}
      <FlavorText>
        The Bubble Cove clan is hoping Baby Shark will grow into a wonderful
        kind of shark. But how would these Puzzmon currently describe them?
      </FlavorText>
      <div className="flex justify-center">
        <ul className="text-center">
          {clues.map((clue, idx) => (
            <li key={idx}>{clue}</li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default PuzzleComponent;
